INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('Antarctic', '남극의', '[{"pos": "a.", "ko": "남극의"}, {"pos": "n.", "ko": "남극 지방"}]'::jsonb, 'The Antarctic region is known for its extremely cold temperatures.', '남극 지역은 매우 추운 기온으로 유명하다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abandon', '버리다', '[{"pos": "v.", "ko": "(사람·장소를) 버리다"}, {"pos": "v.", "ko": "(계획·신념을) 포기하다"}]'::jsonb, 'The hikers had to abandon their campsite due to the sudden storm.', '등산객들은 갑작스러운 폭풍 때문에 야영지를 버려야 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ability', '능력', '[{"pos": "n.", "ko": "능력, 할 수 있음"}]'::jsonb, 'Her ability to solve complex problems impressed her teachers.', '그녀가 복잡한 문제를 푸는 능력은 선생님들에게 깊은 인상을 주었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('able', '~할 수 있는', '[{"pos": "a.", "ko": "~할 수 있는"}, {"pos": "a.", "ko": "유능한"}]'::jsonb, 'You will be able to finish this project if you work hard.', '열심히 하면 이 프로젝트를 끝낼 수 있을 것이다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abnormal', '비정상적인', '[{"pos": "a.", "ko": "비정상적인, 이상한"}]'::jsonb, 'The doctor noticed an abnormal increase in the patient''s heartbeat.', '의사는 환자의 심장 박동이 비정상적으로 증가한 것을 발견했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abnormality', '비정상', '[{"pos": "n.", "ko": "비정상, 이상"}, {"pos": "n.", "ko": "이상 현상"}]'::jsonb, 'The test results showed an abnormality in the blood sample.', '검사 결과 혈액 샘플에서 비정상이 발견되었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('aboard', '탑승하여', '[{"pos": "ad.", "ko": "(배·비행기 등에) 탑승하여"}, {"pos": "prep.", "ko": "~에 탑승한"}]'::jsonb, 'All passengers must be aboard the plane before it departs.', '모든 승객은 비행기가 출발하기 전에 탑승해야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abolish', '폐지하다', '[{"pos": "v.", "ko": "(법·제도 등을) 폐지하다"}, {"pos": "v.", "ko": "없애다"}]'::jsonb, 'The government decided to abolish the outdated law.', '정부는 낡은 법을 폐지하기로 결정했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abolition', '폐지', '[{"pos": "n.", "ko": "(법·제도 등의) 폐지"}]'::jsonb, 'The abolition of slavery was a turning point in history.', '노예제 폐지는 역사에서 중요한 전환점이었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abound', '풍부하다', '[{"pos": "v.", "ko": "풍부하다, 많이 있다"}]'::jsonb, 'Wildflowers abound in the fields during spring.', '봄이 되면 들판에 야생화가 풍부하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abroad', '외국에', '[{"pos": "ad.", "ko": "외국에, 해외로"}, {"pos": "ad.", "ko": "널리 퍼져"}]'::jsonb, 'She plans to study abroad next year to improve her English.', '그녀는 영어 실력을 늘리기 위해 내년에 외국에서 공부할 계획이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('absence', '결석', '[{"pos": "n.", "ko": "결석, 부재"}, {"pos": "n.", "ko": "없음, 결핍"}]'::jsonb, 'His absence from class affected his final grade.', '그가 수업에 결석한 것이 최종 성적에 영향을 미쳤다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('absent', '결석한', '[{"pos": "a.", "ko": "결석한, 없는"}, {"pos": "a.", "ko": "(표정이) 멍한, 집중하지 않는"}, {"pos": "v.", "ko": "결석하다, 결근하다"}]'::jsonb, 'Several students were absent due to the flu outbreak.', '독감 유행으로 여러 학생이 결석했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('absolute', '완전한', '[{"pos": "a.", "ko": "완전한, 전적인"}, {"pos": "a.", "ko": "절대적인"}, {"pos": "a.", "ko": "확실한, 틀림없는"}]'::jsonb, 'The experiment requires absolute silence in the laboratory.', '그 실험은 실험실에서 완전한 정적이 필요하다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
