INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('alive', '살아 있는', '[{"pos": "a.", "ko": "살아 있는"}, {"pos": "a.", "ko": "생기 있는, 활기찬"}]'::jsonb, 'The rescue team found the missing child alive after two days.', '구조대는 이틀 만에 실종된 아이를 살아 있는 채로 발견했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
