INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('alternate', '번갈아 하는', '[{"pos": "a.", "ko": "번갈아 하는, 교대의"}, {"pos": "a.", "ko": "대체의, 대안의"}, {"pos": "v.", "ko": "번갈아 하다, 교대로 하다"}]'::jsonb, 'The team members alternate between working in the office and from home.', '팀원들은 사무실과 집에서 번갈아 일한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
