INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('astronomy', '천문학', '[{"pos": "n.", "ko": "천문학"}, {"pos": "n.", "ko": "우주 과학"}]'::jsonb, 'Astronomy helps us understand the origins of stars and planets.', '천문학은 별과 행성의 기원을 이해하는 데 도움을 준다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
