INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('avoid', '피하다', '[{"pos": "v.", "ko": "피하다"}, {"pos": "v.", "ko": "회피하다"}]'::jsonb, 'You should avoid eating too much junk food for your health.', '건강을 위해서는 정크푸드를 너무 많이 먹는 것을 피해야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
