INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('bad', '나쁜', '[{"pos": "a.", "ko": "나쁜, 좋지 않은"}, {"pos": "a.", "ko": "질이 낮은, 불량한"}, {"pos": "a.", "ko": "아픈, 건강하지 않은"}]'::jsonb, 'Eating too much junk food is bad for your health.', '정크푸드를 너무 많이 먹는 것은 건강에 나쁘다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
