INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conquest', '정복', '[{"pos": "n.", "ko": "정복, 힘으로 차지함"}, {"pos": "n.", "ko": "극복, 어려움을 이겨냄"}, {"pos": "n.", "ko": "획득, 손에 넣음"}]'::jsonb, 'The conquest of the mountain required months of preparation and teamwork.', '그 산을 정복하려면 몇 달간의 준비와 팀워크가 필요했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conscience', '양심', '[{"pos": "n.", "ko": "양심, 옳고 그름을 판단하는 마음"}, {"pos": "n.", "ko": "도덕심, 도덕적 의식"}]'::jsonb, 'Her conscience would not allow her to lie to her friend.', '그녀는 양심 때문에 친구에게 거짓말을 할 수 없었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
