INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conscious', '의식하는', '[{"pos": "a.", "ko": "의식하고 있는, 자각하는"}, {"pos": "a.", "ko": "의식이 있는, 깨어 있는"}, {"pos": "a.", "ko": "의도적인, 일부러 하는"}]'::jsonb, 'She was conscious of the people watching her during the performance.', '그녀는 공연 중에 사람들이 자신을 보고 있다는 것을 의식했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consciousness', '의식', '[{"pos": "n.", "ko": "의식, 깨어있는 상태"}, {"pos": "n.", "ko": "지각, 자각"}, {"pos": "n.", "ko": "(사회·정치적) 인식"}]'::jsonb, 'After the accident, he slowly regained consciousness in the hospital.', '사고 후 그는 병원에서 서서히 의식을 되찾았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consensus', '의견 일치', '[{"pos": "n.", "ko": "의견 일치, 모두의 동의"}, {"pos": "n.", "ko": "합의, 공동의 결정"}]'::jsonb, 'The team reached a consensus after a long discussion.', '팀은 긴 토론 끝에 의견 일치에 도달했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
