INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consequent', '결과로', '[{"pos": "a.", "ko": "결과로 일어나는, 뒤따르는"}]'::jsonb, 'The heavy rain and consequent flooding damaged many houses.', '폭우와 그 결과로 발생한 홍수로 많은 집들이 피해를 입었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
