INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conservation', '보존', '[{"pos": "n.", "ko": "보존, 원래 상태로 지킴"}, {"pos": "n.", "ko": "자연 보호, 환경 보호"}]'::jsonb, 'Wildlife conservation is important for maintaining biodiversity.', '야생동물 보존은 생물 다양성 유지를 위해 중요하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conservative', '보수적인', '[{"pos": "a.", "ko": "보수적인, 전통을 중시하는"}]'::jsonb, 'His parents have conservative views about education.', '그의 부모님은 교육에 대해 보수적인 견해를 가지고 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conserve', '보존하다', '[{"pos": "v.", "ko": "보존하다, 보호하다"}, {"pos": "v.", "ko": "절약하다, 아껴 쓰다"}]'::jsonb, 'We must conserve water to prevent shortages in the future.', '미래의 부족을 막기 위해 우리는 물을 보존해야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consider', '생각하다', '[{"pos": "v.", "ko": "생각하다, 숙고하다"}, {"pos": "v.", "ko": "여기다, 간주하다"}, {"pos": "v.", "ko": "고려하다, 배려하다"}]'::jsonb, 'You should consider all options before making a decision.', '결정하기 전에 모든 선택지를 생각해 봐야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('considerable', '상당한', '[{"pos": "a.", "ko": "상당한, 꽤 많은"}, {"pos": "a.", "ko": "중요한, 주목할 만한"}]'::jsonb, 'The project required a considerable amount of time and effort.', '그 프로젝트는 상당한 시간과 노력이 필요했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('considerably', '상당히', '[{"pos": "ad.", "ko": "상당히, 많이"}]'::jsonb, 'The weather has improved considerably since last week.', '지난주에 비해 날씨가 상당히 좋아졌다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('considerate', '사려 깊은', '[{"pos": "a.", "ko": "사려 깊은, 남을 배려하는"}]'::jsonb, 'It was very considerate of you to help her with her homework.', '네가 그녀의 숙제를 도와준 것은 정말 사려 깊은 행동이었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consideration', '숙고', '[{"pos": "n.", "ko": "숙고, 신중한 생각"}, {"pos": "n.", "ko": "고려, 참작"}, {"pos": "n.", "ko": "배려, 남을 생각함"}]'::jsonb, 'After careful consideration, she decided to accept the offer.', '신중히 숙고한 끝에 그녀는 그 제안을 받아들이기로 했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('considering', '고려하면', '[{"pos": "prep.", "ko": "...을 고려하면"}, {"pos": "conj.", "ko": "...을 생각할 때"}]'::jsonb, 'Considering the weather, we should postpone the picnic.', '날씨를 고려하면 소풍을 미루는 게 좋겠다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consist', '존재하다', '[{"pos": "v.", "ko": "존재하다, 있다"}, {"pos": "v.", "ko": "이루어지다, 구성되다"}]'::jsonb, 'True happiness may consist in appreciating the small things in life.', '진정한 행복은 삶의 작은 것들을 소중히 여기는 데 있을 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consistency', '일관성', '[{"pos": "n.", "ko": "일관성, 한결같음"}, {"pos": "n.", "ko": "(혼합물의) 농도, 밀도"}]'::jsonb, 'Her consistency in studying helped her achieve excellent grades.', '그녀는 꾸준히 공부해서 우수한 성적을 거둘 수 있었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consistent', '일관된', '[{"pos": "a.", "ko": "일관된, 변함없는"}, {"pos": "a.", "ko": "(진술 등이) 일치하는, 모순이 없는"}]'::jsonb, 'He has shown consistent effort throughout the entire semester.', '그는 한 학기 내내 꾸준한 노력을 보여주었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('constant', '끊임없는', '[{"pos": "a.", "ko": "끊임없는, 계속되는"}, {"pos": "a.", "ko": "불변의, 변하지 않는"}, {"pos": "n.", "ko": "상수, 변하지 않는 것"}]'::jsonb, 'The constant noise from the street made it difficult to concentrate.', '거리에서 끊임없이 들려오는 소음 때문에 집중하기 어려웠다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('constantly', '끊임없이', '[{"pos": "ad.", "ko": "끊임없이, 항상"}]'::jsonb, 'She is constantly checking her phone for new messages.', '그녀는 새 메시지가 왔는지 계속 휴대폰을 확인한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
