INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('constitution', '헌법', '[{"pos": "n.", "ko": "헌법"}, {"pos": "n.", "ko": "체질, 체격"}, {"pos": "n.", "ko": "구성, 구조"}]'::jsonb, 'The new law was declared unconstitutional by the Supreme Court.', '새 법률은 대법원에 의해 위헌 판정을 받았다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
