INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('constraint', '제한', '[{"pos": "n.", "ko": "제한, 제약"}]'::jsonb, 'Time constraints prevented us from finishing the project early.', '시간 제약 때문에 우리는 프로젝트를 일찍 끝내지 못했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
