INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('criticize', '비판하다', '[{"pos": "v.", "ko": "비판하다, 비난하다"}, {"pos": "v.", "ko": "비평하다"}]'::jsonb, 'It is easy to criticize others, but harder to offer solutions.', '남을 비판하는 것은 쉽지만 해결책을 제시하는 것은 더 어렵다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('cultivate', '경작하다', '[{"pos": "v.", "ko": "경작하다, 재배하다"}, {"pos": "v.", "ko": "기르다, 계발하다"}]'::jsonb, 'Farmers cultivate the land to grow vegetables and fruits.', '농부들은 채소와 과일을 재배하기 위해 땅을 경작한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('cultivation', '경작', '[{"pos": "n.", "ko": "경작, 재배"}, {"pos": "n.", "ko": "계발, 수양"}]'::jsonb, 'The cultivation of rice requires a lot of water and effort.', '쌀을 경작하려면 많은 물과 노력이 필요하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('cultural', '문화의', '[{"pos": "a.", "ko": "문화의, 문화와 관련된"}, {"pos": "a.", "ko": "예술·문학의"}]'::jsonb, 'Cultural differences can lead to misunderstandings between people from different countries.', '문화적 차이는 서로 다른 나라 사람들 사이에 오해를 불러올 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('culture', '문화', '[{"pos": "n.", "ko": "문화, 한 사회의 생활 방식"}, {"pos": "n.", "ko": "예술·문학 활동"}, {"pos": "n.", "ko": "교양, 세련됨"}]'::jsonb, 'Learning about another culture helps us understand different ways of life.', '다른 문화를 배우면 다양한 삶의 방식을 이해하는 데 도움이 된다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('curable', '치료 가능한', '[{"pos": "a.", "ko": "치료 가능한, 고칠 수 있는"}]'::jsonb, 'Many diseases that were once fatal are now curable with modern medicine.', '한때 치명적이던 많은 질병도 이제는 현대 의학으로 치료할 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('cure', '치료하다', '[{"pos": "v.", "ko": "치료하다, 병을 고치다"}, {"pos": "v.", "ko": "문제를 해결하다"}, {"pos": "n.", "ko": "치료법, 치료약"}]'::jsonb, 'Doctors are working hard to cure patients with rare illnesses.', '의사들은 희귀 질환 환자들을 치료하기 위해 열심히 노력하고 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('curiosity', '호기심', '[{"pos": "n.", "ko": "호기심, 궁금증"}, {"pos": "n.", "ko": "진기한 것, 신기한 물건"}]'::jsonb, 'Children''s curiosity often leads them to ask many questions about the world.', '아이들은 호기심이 많아 세상에 대해 많은 질문을 하곤 한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('curious', '호기심이 많은', '[{"pos": "a.", "ko": "호기심이 많은, 궁금해하는"}, {"pos": "a.", "ko": "이상한, 묘한"}]'::jsonb, 'The curious student stayed after class to ask more questions about the lesson.', '그 호기심 많은 학생은 수업이 끝난 후에도 더 많은 질문을 하려고 남았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('currency', '통화', '[{"pos": "n.", "ko": "통화, 화폐"}, {"pos": "n.", "ko": "(화폐의) 유통, 통용"}]'::jsonb, 'The local currency lost value after the economic crisis.', '경제 위기 이후 그 나라의 통화 가치가 하락했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('current', '현재의', '[{"pos": "a.", "ko": "현재의, 지금의"}, {"pos": "n.", "ko": "(물·공기 등의) 흐름"}, {"pos": "n.", "ko": "(사상·의견 등의) 경향, 풍조"}]'::jsonb, 'The current situation requires everyone to be more careful than usual.', '현재 상황에서는 모두가 평소보다 더 조심해야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('currently', '현재', '[{"pos": "ad.", "ko": "현재, 지금"}]'::jsonb, 'The museum is currently closed for renovations until next month.', '그 박물관은 다음 달까지 리모델링으로 현재 문을 닫았다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('curricular', '교과 과정의', '[{"pos": "a.", "ko": "교과 과정의, 교육 과정의"}]'::jsonb, 'The school is planning several new curricular activities for next semester.', '학교는 다음 학기를 위해 여러 새로운 교과 과정 활동을 계획하고 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('curriculum', '교과 과정', '[{"pos": "n.", "ko": "교과 과정, 교육 과정"}, {"pos": "n.", "ko": "교과목, 수업 내용"}]'::jsonb, 'The curriculum includes both science and humanities subjects.', '그 교과 과정에는 과학과 인문 과목이 모두 포함되어 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('custom', '관습', '[{"pos": "n.", "ko": "관습, 오랜 풍습"}, {"pos": "n.", "ko": "습관"}]'::jsonb, 'It is a custom in some countries to take off your shoes indoors.', '일부 나라에서는 실내에서 신발을 벗는 것이 관습이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('customary', '관례적인', '[{"pos": "a.", "ko": "관례적인, 통상적인"}, {"pos": "a.", "ko": "습관적인"}]'::jsonb, 'It is customary to shake hands when meeting someone for the first time.', '처음 만나는 사람과는 악수하는 것이 관례이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
