INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('disruption', '혼란', '[{"pos": "n.", "ko": "혼란, 방해"}, {"pos": "n.", "ko": "붕괴, 파열"}]'::jsonb, 'The sudden power outage caused major disruption at the hospital.', '갑작스런 정전으로 병원에 큰 혼란이 발생했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
