INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('district', '지구', '[{"pos": "n.", "ko": "지구, 행정 구역"}, {"pos": "n.", "ko": "지역, 특정 구역"}]'::jsonb, 'She moved to a new school in another district last year.', '그녀는 작년에 다른 지구에 있는 새 학교로 전학 갔다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('disturb', '방해하다', '[{"pos": "v.", "ko": "방해하다, 집중을 깨뜨리다"}, {"pos": "v.", "ko": "어지럽히다, 평온을 깨다"}]'::jsonb, 'Please do not disturb the students while they are taking the test.', '학생들이 시험을 보는 동안 방해하지 마세요.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
