INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emergent', '신생의', '[{"pos": "a.", "ko": "신생의, 새로 나타난"}, {"pos": "a.", "ko": "급격히 성장하는"}]'::jsonb, 'Emergent industries often drive economic growth in developing countries.', '신생 산업은 종종 개발도상국의 경제 성장을 이끈다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emigrant', '이민자', '[{"pos": "n.", "ko": "(타국으로 가는) 이민자, 이주자"}]'::jsonb, 'Many emigrants left their homeland in search of better opportunities.', '많은 이민자들이 더 나은 기회를 찾아 고국을 떠났다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emigrate', '이민 가다', '[{"pos": "v.", "ko": "이민 가다, 이주하다"}]'::jsonb, 'Her family decided to emigrate to Canada for a new life.', '그녀의 가족은 새로운 삶을 위해 캐나다로 이민 가기로 결정했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emigration', '이민', '[{"pos": "n.", "ko": "이민, 이주 (타국으로 떠남)"}]'::jsonb, 'The country experienced a wave of emigration during the economic crisis.', '그 나라는 경제 위기 동안 이민이 급증했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('eminent', '저명한', '[{"pos": "a.", "ko": "저명한, 뛰어난"}, {"pos": "a.", "ko": "존경받는"}]'::jsonb, 'An eminent scientist gave a lecture at the international conference.', '저명한 과학자가 국제 학회에서 강연했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('eminently', '대단히', '[{"pos": "ad.", "ko": "대단히, 매우"}, {"pos": "ad.", "ko": "탁월하게"}]'::jsonb, 'The proposal was eminently practical and easy to implement.', '그 제안은 대단히 실용적이고 실행하기 쉬웠다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emission', '배출', '[{"pos": "n.", "ko": "배출, 방출 (가스, 빛 등)"}, {"pos": "n.", "ko": "배출물, 방출된 것"}]'::jsonb, 'Car emission standards have become stricter to protect the environment.', '환경 보호를 위해 자동차 배출 기준이 더 엄격해졌다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emit', '내뿜다', '[{"pos": "v.", "ko": "내뿜다, 방출하다"}, {"pos": "v.", "ko": "(소리·빛 등을) 내다"}]'::jsonb, 'The factory emits smoke into the air, causing pollution.', '그 공장은 연기를 내뿜어 대기 오염을 일으킨다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emotion', '감정', '[{"pos": "n.", "ko": "감정, 정서"}]'::jsonb, 'He tried to hide his emotion during the farewell ceremony.', '그는 이별식에서 자신의 감정을 숨기려 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emotional', '감정의', '[{"pos": "a.", "ko": "감정의, 정서적인"}, {"pos": "a.", "ko": "감정적인, 감정에 치우친"}]'::jsonb, 'She gave an emotional speech that moved everyone in the audience.', '그녀는 모든 청중을 감동시킨 감정이 담긴 연설을 했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empathetic', '공감하는', '[{"pos": "a.", "ko": "감정을 이입하는, 공감하는"}]'::jsonb, 'An empathetic teacher listens carefully to students'' concerns.', '공감하는 선생님은 학생들의 고민을 잘 들어준다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empathize', '공감하다', '[{"pos": "v.", "ko": "공감하다, 감정 이입하다"}]'::jsonb, 'It is important to empathize with others when they are struggling.', '다른 사람이 힘들어할 때 공감해 주는 것이 중요하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empathy', '공감', '[{"pos": "n.", "ko": "공감, 감정 이입"}]'::jsonb, 'Empathy helps people build strong and supportive relationships.', '공감은 사람들이 돈독하고 서로 돕는 관계를 만드는 데 도움이 된다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emperor', '황제', '[{"pos": "n.", "ko": "황제, 제왕"}]'::jsonb, 'The emperor ruled the vast empire for over thirty years.', '황제는 30년 넘게 거대한 제국을 다스렸다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emphasis', '강조', '[{"pos": "n.", "ko": "강조, 특별히 힘을 줌"}, {"pos": "n.", "ko": "중요성, 중점"}, {"pos": "n.", "ko": "강세, 음성에서의 힘"}]'::jsonb, 'The teacher placed special emphasis on the importance of reading every day.', '선생님은 매일 독서의 중요성을 특별히 강조했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emphasize', '강조하다', '[{"pos": "v.", "ko": "강조하다, 두드러지게 하다"}, {"pos": "v.", "ko": "중요하게 여기다"}, {"pos": "v.", "ko": "강하게 발음하다"}]'::jsonb, 'The coach emphasized the need for teamwork before the game started.', '감독은 경기가 시작되기 전에 팀워크의 필요성을 강조했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empire', '제국', '[{"pos": "n.", "ko": "제국, 여러 나라를 다스리는 국가"}, {"pos": "n.", "ko": "거대 조직, 대기업"}, {"pos": "n.", "ko": "지배권, 통치"}]'::jsonb, 'The Roman Empire was known for its vast territory and powerful army.', '로마 제국은 광대한 영토와 강력한 군대로 유명했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('employ', '고용하다', '[{"pos": "v.", "ko": "고용하다, 일자리를 주다"}, {"pos": "v.", "ko": "(방법·기술 등을) 사용하다"}, {"pos": "v.", "ko": "시간을 쓰다"}]'::jsonb, 'The company decided to employ more workers for the new project.', '그 회사는 새 프로젝트를 위해 더 많은 직원을 고용하기로 결정했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
