INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('employment', '고용', '[{"pos": "n.", "ko": "고용, 일자리 제공"}, {"pos": "n.", "ko": "직업, 취업"}, {"pos": "n.", "ko": "사용, 활용"}]'::jsonb, 'The government is working to increase employment among young people.', '정부는 청년층의 고용을 늘리기 위해 노력하고 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empress', '여자 황제', '[{"pos": "n.", "ko": "여자 황제, 여성 통치자"}, {"pos": "n.", "ko": "황후, 황제의 아내"}]'::jsonb, 'The empress ruled the country with wisdom and kindness.', '여자 황제는 지혜와 자비로 나라를 다스렸다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
