INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('encouragement', '격려', '[{"pos": "n.", "ko": "격려, 용기를 북돋움"}, {"pos": "n.", "ko": "장려, 조장"}]'::jsonb, 'A few words of encouragement can make a big difference to someone.', '격려의 한마디가 누군가에게 큰 힘이 될 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('endless', '끝없는', '[{"pos": "a.", "ko": "끝없는, 무한한"}, {"pos": "a.", "ko": "지루하게 긴"}]'::jsonb, 'The endless desert stretched far beyond what we could see.', '끝없는 사막이 우리가 볼 수 있는 곳 너머까지 펼쳐져 있었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enforce', '시행하다', '[{"pos": "v.", "ko": "(법률 등을) 시행하다, 집행하다"}, {"pos": "v.", "ko": "강요하다, 강제로 시키다"}]'::jsonb, 'The government must enforce strict laws to protect the environment.', '정부는 환경을 보호하기 위해 엄격한 법을 시행해야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
