INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('essence', '본질', '[{"pos": "n.", "ko": "본질, 핵심"}, {"pos": "n.", "ko": "정수, 진수"}, {"pos": "n.", "ko": "(식물 등에서 추출한) 원액"}]'::jsonb, 'The essence of good leadership is the ability to inspire others.', '좋은 리더십의 본질은 다른 사람에게 영감을 주는 능력이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
