INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('evade', '회피하다', '[{"pos": "v.", "ko": "회피하다, 피하다"}, {"pos": "v.", "ko": "탈출하다, 빠져나가다"}]'::jsonb, 'He tried to evade answering the difficult question in the interview.', '그는 면접에서 어려운 질문에 답하는 것을 회피하려 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
