INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('exaggerate', '과장하다', '[{"pos": "v.", "ko": "과장하다, 지나치게 부풀리다"}]'::jsonb, 'He tends to exaggerate his achievements when talking to others.', '그는 다른 사람들과 이야기할 때 자신의 성과를 과장하는 경향이 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
