INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('expensive', '비싼', '[{"pos": "a.", "ko": "비싼, 가격이 높은"}, {"pos": "a.", "ko": "많은 비용이 드는"}, {"pos": "a.", "ko": "값비싼, 사치스러운"}]'::jsonb, 'This smartphone is too expensive for most students to buy.', '이 스마트폰은 대부분의 학생들이 사기에는 너무 비싸다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
