INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('explore', '탐험하다', '[{"pos": "v.", "ko": "탐험하다, 미지의 곳을 찾다"}, {"pos": "v.", "ko": "탐구하다, 연구하다"}, {"pos": "v.", "ko": "조사하다, 살펴보다"}]'::jsonb, 'Scientists plan to explore the deepest parts of the ocean next year.', '과학자들은 내년에 바다의 가장 깊은 곳을 탐험할 계획이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
