INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('exposure', '노출', '[{"pos": "n.", "ko": "노출, 드러남"}, {"pos": "n.", "ko": "폭로, 탄로"}]'::jsonb, 'Prolonged exposure to loud noise can damage your hearing.', '오랜 시간 큰 소음에 노출되면 청력이 손상될 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
