INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('fragile', '깨지기 쉬운', '[{"pos": "a.", "ko": "깨지기 쉬운, 부서지기 쉬운"}, {"pos": "a.", "ko": "허약한, 연약한"}]'::jsonb, 'Be careful with the fragile glass vase when you move it.', '그 유리 꽃병은 깨지기 쉬우니 옮길 때 조심해.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
