INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('fragrant', '향기로운', '[{"pos": "a.", "ko": "향기로운, 향긋한"}]'::jsonb, 'The garden was filled with fragrant flowers in the spring air.', '정원은 봄바람에 향기로운 꽃들로 가득했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('frighten', '무섭게 하다', '[{"pos": "v.", "ko": "겁을 주다, 무섭게 하다"}, {"pos": "v.", "ko": "놀라게 하다"}]'::jsonb, 'The loud thunder was enough to frighten the small children.', '큰 천둥 소리에 아이들이 무서워했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('frustrate', '좌절시키다', '[{"pos": "v.", "ko": "좌절시키다, 실망하게 하다"}, {"pos": "v.", "ko": "방해하다, 좌절하게 만들다"}]'::jsonb, 'Unexpected problems can frustrate even the best-laid plans.', '예상치 못한 문제들이 아무리 잘 세운 계획도 좌절시킬 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
