INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('furious', '격노한', '[{"pos": "a.", "ko": "몹시 화가 난, 격노한"}, {"pos": "a.", "ko": "맹렬한, 격렬한"}]'::jsonb, 'He was furious when he discovered the truth about the incident.', '그는 사건의 진실을 알게 되자 격노했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
