INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('generous', '관대한', '[{"pos": "a.", "ko": "관대한, 너그러운"}, {"pos": "a.", "ko": "풍부한, 넉넉한"}]'::jsonb, 'He was generous with his time and always willing to help others.', '그는 시간을 아끼지 않고 항상 다른 사람을 도왔다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('genetic', '유전의', '[{"pos": "a.", "ko": "유전의, 유전과 관련된"}, {"pos": "a.", "ko": "유전학의"}]'::jsonb, 'Many diseases have a genetic cause that can be traced in families.', '많은 질병은 가족 내에서 유전적인 원인을 가진다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
