INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('genetics', '유전학', '[{"pos": "n.", "ko": "유전학, 유전의 원리를 연구하는 학문"}]'::jsonb, 'She decided to study genetics because she was interested in heredity.', '그녀는 유전에 관심이 있어서 유전학을 공부하기로 했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('genius', '천재', '[{"pos": "n.", "ko": "천재, 비범한 재능을 가진 사람"}, {"pos": "n.", "ko": "비상한 재능, 뛰어난 능력"}]'::jsonb, 'The young composer was recognized as a musical genius by many critics.', '그 젊은 작곡가는 많은 평론가들에게 음악적 천재로 인정받았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('gentle', '온화한', '[{"pos": "a.", "ko": "온화한, 성격이 부드러운"}, {"pos": "a.", "ko": "상냥한, 친절한"}, {"pos": "a.", "ko": "부드러운, 세기가 약한"}]'::jsonb, 'He has a gentle voice that makes everyone feel comfortable.', '그는 모두를 편안하게 해 주는 온화한 목소리를 가지고 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
