INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hasty', '성급한', '[{"pos": "a.", "ko": "성급한, 급한"}, {"pos": "a.", "ko": "서두르는, 조급한"}]'::jsonb, 'A hasty decision can sometimes lead to mistakes.', '성급한 결정은 때때로 실수를 부를 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('heir', '상속인', '[{"pos": "n.", "ko": "상속인, 후계자"}]'::jsonb, 'He became the heir to his family''s estate after his father passed away.', '그는 아버지가 돌아가신 후 집안 재산의 상속인이 되었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('helpless', '무력한', '[{"pos": "a.", "ko": "무력한, 속수무책인"}, {"pos": "a.", "ko": "감당하지 못하는"}]'::jsonb, 'The kitten looked helpless in the middle of the busy street.', '그 새끼 고양이는 번화한 거리 한가운데서 무력해 보였다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('helplessness', '무력감', '[{"pos": "n.", "ko": "무력감, 난감함"}]'::jsonb, 'He felt a deep sense of helplessness when he couldn''t solve the problem.', '그는 문제를 해결하지 못해 깊은 무력감을 느꼈다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hemisphere', '반구', '[{"pos": "n.", "ko": "반구, (지구·뇌의) 반구"}]'::jsonb, 'The northern hemisphere experiences winter while the southern hemisphere has summer.', '북반구가 겨울일 때 남반구는 여름이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hereditary', '유전성의', '[{"pos": "a.", "ko": "유전되는, 유전성의"}, {"pos": "a.", "ko": "세습되는, 대물림되는"}]'::jsonb, 'Some diseases are hereditary and can be passed from parents to children.', '어떤 질병들은 유전되어 부모에게서 자식에게 전달될 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('heredity', '유전', '[{"pos": "n.", "ko": "유전, 유전적 특성"}, {"pos": "n.", "ko": "세습"}]'::jsonb, 'Heredity plays a key role in determining a person''s eye color.', '유전은 한 사람의 눈 색깔을 결정하는 데 중요한 역할을 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('heritage', '문화유산', '[{"pos": "n.", "ko": "전통, 문화유산"}, {"pos": "n.", "ko": "상속재산, 유산"}]'::jsonb, 'The city is famous for its rich cultural heritage and historic sites.', '그 도시는 풍부한 문화유산과 역사적 명소로 유명하다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('high', '높은', '[{"pos": "a.", "ko": "높은, 키가 큰"}, {"pos": "ad.", "ko": "높이, 위쪽에"}, {"pos": "a.", "ko": "수준이 높은, 고급의"}]'::jsonb, 'The mountain is so high that its peak is covered with snow all year.', '그 산은 매우 높아서 정상에 1년 내내 눈이 덮여 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('highly', '매우', '[{"pos": "ad.", "ko": "매우, 대단히"}, {"pos": "ad.", "ko": "높이 평가하여"}]'::jsonb, 'The new movie was highly recommended by many critics.', '그 새 영화는 많은 평론가들에게 매우 추천받았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('historic', '역사적', '[{"pos": "a.", "ko": "역사적으로 중요한, 역사에 남을"}, {"pos": "a.", "ko": "유서 깊은"}]'::jsonb, 'The historic agreement changed the relationship between the two countries.', '그 역사적인 합의는 두 나라의 관계를 바꿔 놓았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('historical', '역사상의', '[{"pos": "a.", "ko": "역사상의, 실제 있었던"}, {"pos": "a.", "ko": "역사에 관한, 역사와 관련된"}]'::jsonb, 'The museum displays many historical artifacts from ancient times.', '그 박물관은 고대의 많은 역사적 유물을 전시하고 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('homeward', '집으로', '[{"pos": "ad.", "ko": "집으로, 집 쪽으로"}, {"pos": "a.", "ko": "집으로 향하는"}]'::jsonb, 'After the meeting, everyone walked homeward in the rain.', '회의가 끝난 후, 모두가 비를 맞으며 집으로 걸어갔다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hopeful', '희망에 찬', '[{"pos": "a.", "ko": "희망에 찬, 기대하는"}, {"pos": "a.", "ko": "유망한, 장래가 밝은"}]'::jsonb, 'She is hopeful that she will pass the entrance exam this year.', '그녀는 올해 입학시험에 합격할 것이라고 희망에 차 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hospitable', '환대하는', '[{"pos": "a.", "ko": "환대하는, 친절한"}, {"pos": "a.", "ko": "대접이 후한"}]'::jsonb, 'The villagers were very hospitable to the new visitors.', '마을 사람들은 새로 온 방문객들에게 매우 환대했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hospitality', '환대', '[{"pos": "n.", "ko": "환대, 후한 대접"}, {"pos": "n.", "ko": "친절"}]'::jsonb, 'We were touched by their hospitality during our stay.', '우리는 머무는 동안 그들의 환대에 감동했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('host', '주인', '[{"pos": "n.", "ko": "주인, 손님을 초대한 사람"}, {"pos": "n.", "ko": "행사 주최자, 진행자"}, {"pos": "v.", "ko": "행사를 주최하다"}, {"pos": "v.", "ko": "프로그램을 진행하다"}]'::jsonb, 'The host greeted each guest as they arrived at the party.', '주인은 파티에 도착한 손님 한 명 한 명을 맞이했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hostess', '여주인', '[{"pos": "n.", "ko": "여성 주최자, 여주인"}, {"pos": "n.", "ko": "여성 진행자"}, {"pos": "n.", "ko": "여성 접대원"}]'::jsonb, 'The hostess greeted each guest warmly at the entrance to the party.', '여주인은 파티 입구에서 손님 한 명 한 명을 따뜻하게 맞이했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hostile', '적대적인', '[{"pos": "a.", "ko": "적대적인, 공격적인"}, {"pos": "a.", "ko": "비우호적인, 냉담한"}]'::jsonb, 'The two countries have maintained a hostile relationship for many years.', '두 나라는 오랫동안 적대적인 관계를 유지해 왔다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hostility', '적의', '[{"pos": "n.", "ko": "적의, 적개심"}, {"pos": "n.", "ko": "적대 행위"}]'::jsonb, 'There was clear hostility between the two teams during the match.', '경기 내내 두 팀 사이에는 뚜렷한 적의가 느껴졌다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('human', '인간의', '[{"pos": "a.", "ko": "인간의, 사람의"}, {"pos": "n.", "ko": "인간, 사람"}]'::jsonb, 'Human activities have a significant impact on the environment.', '인간의 활동은 환경에 큰 영향을 미친다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('humane', '인도적인', '[{"pos": "a.", "ko": "인도적인, 자비로운"}, {"pos": "a.", "ko": "동정심 있는"}]'::jsonb, 'The organization is known for its humane treatment of animals.', '그 단체는 동물에게 인도적으로 대하는 것으로 유명하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('humanity', '인류', '[{"pos": "n.", "ko": "인류, 인간 전체"}, {"pos": "n.", "ko": "인간성, 인간다움"}]'::jsonb, 'Climate change is a major challenge for all of humanity.', '기후 변화는 전 인류가 직면한 큰 도전이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('humble', '겸손한', '[{"pos": "a.", "ko": "겸손한, 자만하지 않는"}, {"pos": "a.", "ko": "소박한, 검소한"}, {"pos": "v.", "ko": "겸손하게 만들다, 낮추다"}]'::jsonb, 'Despite his success, he remains a humble person who helps others.', '그는 성공했음에도 불구하고 여전히 겸손하게 다른 사람을 돕는다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('humiliate', '굴욕감을 주다', '[{"pos": "v.", "ko": "굴욕감을 주다, 창피를 주다"}]'::jsonb, 'The teacher did not want to humiliate the student in front of the class.', '선생님은 학생을 반 친구들 앞에서 굴욕감 주고 싶지 않았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('humiliation', '굴욕', '[{"pos": "n.", "ko": "굴욕, 창피"}, {"pos": "n.", "ko": "수치스러운 일"}]'::jsonb, 'He felt deep humiliation after losing the game in front of everyone.', '그는 모두 앞에서 경기에 져서 깊은 굴욕을 느꼈다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('humility', '겸손', '[{"pos": "n.", "ko": "겸손, 겸허"}]'::jsonb, 'True leaders show humility even when they achieve great things.', '진정한 리더는 큰 성과를 내도 겸손함을 잃지 않는다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hypothesis', '가설', '[{"pos": "n.", "ko": "가설, 추정"}, {"pos": "n.", "ko": "가정, 전제"}]'::jsonb, 'The scientist tested her hypothesis through a series of experiments.', '과학자는 여러 실험을 통해 자신의 가설을 검증했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('hypothetical', '가설의', '[{"pos": "a.", "ko": "가설의, 가정의"}, {"pos": "a.", "ko": "가상의"}]'::jsonb, 'They discussed a hypothetical situation to better understand the problem.', '그들은 문제를 더 잘 이해하기 위해 가설적인 상황을 논의했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ideal', '이상적인', '[{"pos": "a.", "ko": "이상적인, 완벽한"}, {"pos": "n.", "ko": "이상, 이상형"}]'::jsonb, 'This quiet park is an ideal place to study or relax.', '이 조용한 공원은 공부하거나 쉬기에 이상적인 곳이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('idealist', '이상주의자', '[{"pos": "n.", "ko": "이상주의자, 이상을 추구하는 사람"}]'::jsonb, 'As an idealist, she always believes in a better future for everyone.', '그녀는 이상주의자여서 항상 모두의 더 나은 미래를 믿는다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('idealistic', '이상주의적인', '[{"pos": "a.", "ko": "이상주의적인, 현실보다 이상을 중시하는"}, {"pos": "a.", "ko": "비현실적으로 낙관적인"}]'::jsonb, 'Her idealistic views inspire others to believe in a better world.', '그녀의 이상주의적인 관점은 다른 이들에게 더 나은 세상을 믿게 한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('idealize', '이상화하다', '[{"pos": "v.", "ko": "이상적으로 여기다, 이상화하다"}, {"pos": "v.", "ko": "실제보다 더 완벽하게 생각하다"}]'::jsonb, 'Many people tend to idealize their childhood memories as perfect times.', '많은 사람들이 어린 시절의 기억을 완벽한 시절로 이상화하는 경향이 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ideally', '이상적으로', '[{"pos": "ad.", "ko": "이상적으로, 가장 바람직하게"}, {"pos": "ad.", "ko": "완벽하게, 최선의 방법으로"}]'::jsonb, 'Ideally, everyone should have equal access to education and healthcare.', '이상적으로는 모두가 교육과 의료에 동등하게 접근할 수 있어야 한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('identical', '동일한', '[{"pos": "a.", "ko": "똑같은, 동일한"}, {"pos": "a.", "ko": "완전히 일치하는"}]'::jsonb, 'The twins wore identical clothes, making it hard to tell them apart.', '쌍둥이들은 똑같은 옷을 입어서 구별하기 어려웠다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('identification', '신분 증명', '[{"pos": "n.", "ko": "신원 확인, 신분 증명"}, {"pos": "n.", "ko": "신분증, 신분 증명서"}, {"pos": "n.", "ko": "동일시, 동질감"}]'::jsonb, 'You must show proper identification before entering the examination room.', '시험장에 들어가기 전에 신분증을 반드시 제시해야 한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('identify', '확인하다', '[{"pos": "v.", "ko": "확인하다, 식별하다"}, {"pos": "v.", "ko": "(…와) 동일시하다, 연관 짓다"}]'::jsonb, 'The police were able to identify the suspect using security camera footage.', '경찰은 보안 카메라 영상을 통해 용의자를 확인할 수 있었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('identity', '신원', '[{"pos": "n.", "ko": "신원, 정체"}, {"pos": "n.", "ko": "정체성, 개성"}, {"pos": "n.", "ko": "동일함, 일치"}]'::jsonb, 'Protecting your online identity is important in the digital age.', '디지털 시대에는 온라인 신원을 보호하는 것이 중요하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ignorance', '무지', '[{"pos": "n.", "ko": "무지, 알지 못함"}, {"pos": "n.", "ko": "무식, 정보 부족"}]'::jsonb, 'Many problems in society arise from ignorance and lack of understanding.', '사회 문제의 상당수는 무지와 이해 부족에서 비롯된다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ignorant', '무지한', '[{"pos": "a.", "ko": "무지한, 잘 모르는"}, {"pos": "a.", "ko": "교육받지 못한"}]'::jsonb, 'He was ignorant of the rules and made several mistakes.', '그는 규칙을 몰라서 실수를 여러 번 했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ignore', '무시하다', '[{"pos": "v.", "ko": "무시하다, 못 본 척하다"}, {"pos": "v.", "ko": "관심을 두지 않다"}]'::jsonb, 'You should not ignore the warning signs of stress in your body.', '몸에서 나타나는 스트레스 신호를 무시해서는 안 된다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illegal', '불법의', '[{"pos": "a.", "ko": "불법의, 법에 어긋나는"}]'::jsonb, 'It is illegal to drive without a valid license in most countries.', '대부분의 나라에서 유효한 면허 없이 운전하는 것은 불법이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illegally', '불법적으로', '[{"pos": "ad.", "ko": "불법적으로, 위법하게"}]'::jsonb, 'The company was fined for dumping waste illegally into the river.', '그 회사는 강에 불법적으로 폐기물을 버려 벌금을 물었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illusion', '착각', '[{"pos": "n.", "ko": "착각, 오해"}, {"pos": "n.", "ko": "환영, 환상"}]'::jsonb, 'The magician created the illusion that he could make objects disappear.', '마술사는 물건이 사라지는 것 같은 착각을 불러일으켰다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illusionary', '환영의', '[{"pos": "a.", "ko": "환영의, 실제와 다른"}, {"pos": "a.", "ko": "착각의, 허상의"}]'::jsonb, 'The promise of instant success is often illusionary and misleading.', '즉각적인 성공에 대한 약속은 대개 환영에 불과하고 오해를 불러일으킨다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illusionist', '마술사', '[{"pos": "n.", "ko": "마술사, 환영을 만드는 사람"}]'::jsonb, 'The illusionist amazed the audience with his incredible tricks on stage.', '마술사는 무대에서 놀라운 묘기로 관객을 감탄하게 했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illusive', '환영인', '[{"pos": "a.", "ko": "환영 같은, 실제와 다른"}, {"pos": "a.", "ko": "착각을 일으키는"}]'::jsonb, 'The treasure they searched for turned out to be illusive and unreachable.', '그들이 찾던 보물은 환영에 불과하고 손에 닿지 않는 것이었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illustrate', '설명하다', '[{"pos": "v.", "ko": "설명하다, 예시를 들다"}, {"pos": "v.", "ko": "삽화를 넣다"}]'::jsonb, 'The teacher used a diagram to illustrate how the water cycle works.', '선생님은 물의 순환 과정을 설명하기 위해 도표를 사용했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illustration', '삽화', '[{"pos": "n.", "ko": "삽화, 그림"}, {"pos": "n.", "ko": "예시, 설명"}]'::jsonb, 'The book contains colorful illustrations that help readers understand the story.', '그 책에는 독자가 이야기를 이해하는 데 도움이 되는 색감 있는 삽화가 들어 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('imaginable', '상상할 수 있는', '[{"pos": "a.", "ko": "상상할 수 있는, 생각할 수 있는"}]'::jsonb, 'The festival offered every imaginable type of food from around the world.', '그 축제에는 세계 각국의 상상할 수 있는 모든 종류의 음식이 있었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
