INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('imaginative', '상상력이 풍부한', '[{"pos": "a.", "ko": "상상력이 풍부한"}, {"pos": "a.", "ko": "창의적인"}, {"pos": "a.", "ko": "독창적인"}]'::jsonb, 'The teacher praised her for her imaginative solution to the problem.', '선생님은 그녀의 상상력이 풍부한 문제 해결법을 칭찬했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('imitate', '모방하다', '[{"pos": "v.", "ko": "모방하다"}, {"pos": "v.", "ko": "흉내내다"}, {"pos": "v.", "ko": "따라하다"}]'::jsonb, 'Children often imitate the behavior of adults around them.', '아이들은 주변 어른들의 행동을 자주 모방한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
