INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intentional', '의도적인', '[{"pos": "a.", "ko": "의도적인, 고의의"}]'::jsonb, 'The mistake was not intentional but happened by accident.', '그 실수는 의도적인 것이 아니라 우연히 일어난 일이었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intentionally', '의도적으로', '[{"pos": "ad.", "ko": "의도적으로, 고의로"}]'::jsonb, 'He intentionally left the door open so his friend could enter quietly.', '그는 친구가 조용히 들어올 수 있도록 일부러 문을 열어 두었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interact', '상호 작용하다', '[{"pos": "v.", "ko": "상호 작용하다, 서로 영향을 주다"}]'::jsonb, 'Students are encouraged to interact with each other during group projects.', '학생들은 조별 과제에서 서로 상호 작용하도록 권장된다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interaction', '상호 작용', '[{"pos": "n.", "ko": "상호 작용, 상호 영향"}]'::jsonb, 'The interaction between teachers and students improves learning outcomes.', '교사와 학생 간의 상호 작용이 학습 효과를 높인다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interactive', '쌍방향의', '[{"pos": "a.", "ko": "상호 작용하는, 쌍방향의"}]'::jsonb, 'The interactive program lets users choose their own learning path.', '그 쌍방향 프로그램은 사용자가 학습 경로를 직접 선택할 수 있게 한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interfere', '간섭하다', '[{"pos": "v.", "ko": "간섭하다, 참견하다"}, {"pos": "v.", "ko": "방해하다, 지장을 주다"}]'::jsonb, 'Parents should not interfere too much in their children''s friendships.', '부모는 자녀의 친구 관계에 지나치게 간섭하지 않는 것이 좋다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interference', '간섭', '[{"pos": "n.", "ko": "간섭, 방해"}]'::jsonb, 'The interference from loud noises made it hard to concentrate on the test.', '시끄러운 소음의 간섭 때문에 시험에 집중하기가 어려웠다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intermediate', '중간 단계의', '[{"pos": "a.", "ko": "중간 단계의, 중간의"}, {"pos": "a.", "ko": "중급의"}, {"pos": "n.", "ko": "중급자"}]'::jsonb, 'She took an intermediate English class to improve her language skills.', '그녀는 영어 실력을 높이기 위해 중간 단계 수업을 들었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('internal', '내부의', '[{"pos": "a.", "ko": "내부의, 안쪽의"}, {"pos": "a.", "ko": "내적인, 마음속의"}]'::jsonb, 'The company is investigating an internal problem in its computer system.', '그 회사는 컴퓨터 시스템의 내부 문제를 조사하고 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
