INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('internally', '내부로', '[{"pos": "ad.", "ko": "내부로, 안에서"}, {"pos": "ad.", "ko": "내적으로, 마음속으로"}]'::jsonb, 'The machine was damaged internally, so it had to be repaired.', '그 기계는 내부로 손상되어 수리가 필요했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('international', '국제적인', '[{"pos": "a.", "ko": "국제적인, 나라 사이의"}, {"pos": "a.", "ko": "국가 간의"}]'::jsonb, 'She attended an international conference on climate change last year.', '그녀는 지난해 기후 변화에 관한 국제 회의에 참석했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interpret', '통역하다', '[{"pos": "v.", "ko": "통역하다, 다른 언어로 옮기다"}, {"pos": "v.", "ko": "해석하다, 의미를 파악하다"}, {"pos": "v.", "ko": "연주하다, 연기하다"}]'::jsonb, 'He was asked to interpret for the foreign guests during the meeting.', '그는 회의 중 외국 손님들을 위해 통역해 달라는 요청을 받았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interpretation', '해석', '[{"pos": "n.", "ko": "해석, 의미 설명"}, {"pos": "n.", "ko": "설명, 해설"}]'::jsonb, 'The poem allows for more than one interpretation by its readers.', '그 시는 독자들이 여러 가지로 해석할 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interpreter', '통역관', '[{"pos": "n.", "ko": "통역관, 통역자"}]'::jsonb, 'The interpreter translated the speaker''s words into three different languages.', '통역관은 연설자의 말을 세 가지 언어로 번역했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interrupt', '방해하다', '[{"pos": "v.", "ko": "방해하다, 말을 끊다"}, {"pos": "v.", "ko": "중단시키다, 멈추게 하다"}]'::jsonb, 'Please do not interrupt me while I am speaking.', '내가 말하는 동안 방해하지 마세요.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interruption', '방해', '[{"pos": "n.", "ko": "방해, 끼어듦"}, {"pos": "n.", "ko": "중단, 일시 정지"}]'::jsonb, 'The sudden interruption made it hard for him to finish his presentation.', '갑작스러운 방해로 그는 발표를 끝내기 어려웠다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
