INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interval', '간격', '[{"pos": "n.", "ko": "간격, 사이"}, {"pos": "n.", "ko": "(공연 등의) 중간 휴식 시간"}]'::jsonb, 'There was a five-minute interval between the two matches.', '두 경기 사이에 5분간의 간격이 있었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intervene', '중재하다', '[{"pos": "v.", "ko": "중재하다, 개입하다"}, {"pos": "v.", "ko": "끼어들다, 방해하다"}, {"pos": "v.", "ko": "(사건이) 사이에 일어나다"}]'::jsonb, 'The teacher had to intervene in the argument to calm the students.', '선생님이 학생들을 진정시키기 위해 언쟁에 중재해야 했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intervention', '중재', '[{"pos": "n.", "ko": "중재, 개입"}, {"pos": "n.", "ko": "간섭, 조정"}]'::jsonb, 'Without government intervention, the situation could have become worse.', '정부의 중재가 없었다면 상황이 더 악화될 수 있었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interview', '면접', '[{"pos": "n.", "ko": "면접, 인터뷰"}, {"pos": "v.", "ko": "면접하다, 인터뷰하다"}]'::jsonb, 'He prepared carefully for his job interview next week.', '그는 다음 주에 있을 취업 면접을 꼼꼼히 준비했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interviewee', '면접 대상자', '[{"pos": "n.", "ko": "면접 대상자, 인터뷰 받는 사람"}]'::jsonb, 'Each interviewee was given ten minutes to answer the questions.', '각 면접 대상자에게는 질문에 답할 시간이 10분 주어졌다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('interviewer', '면접관', '[{"pos": "n.", "ko": "면접관, 인터뷰 진행자"}]'::jsonb, 'The interviewer asked about my strengths and weaknesses during the meeting.', '면접관은 면접 중에 내 강점과 약점에 대해 물었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intimacy', '친밀함', '[{"pos": "n.", "ko": "친밀함, 가까움"}]'::jsonb, 'A strong sense of intimacy can strengthen relationships between friends.', '친밀감이 강하면 친구 사이의 관계가 더 돈독해질 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intimate', '친밀한', '[{"pos": "a.", "ko": "친밀한, 가까운"}]'::jsonb, 'They have been intimate friends since they were in elementary school.', '그들은 초등학교 때부터 친밀한 친구로 지내왔다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intonation', '억양', '[{"pos": "n.", "ko": "억양, 말의 높낮이"}, {"pos": "n.", "ko": "어조, 말투"}, {"pos": "n.", "ko": "음악의 음조"}]'::jsonb, 'You can often tell someone’s mood by the intonation of their voice.', '사람의 목소리 억양만으로도 그 사람의 기분을 알 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('introduce', '소개하다', '[{"pos": "v.", "ko": "(사람을) 소개하다"}, {"pos": "v.", "ko": "(제도·물건 등을) 도입하다, 처음으로 선보이다"}, {"pos": "v.", "ko": "(주제를) 제시하다"}]'::jsonb, 'Let me introduce my friend who just moved to this city.', '이 도시에 막 이사 온 제 친구를 소개할게요.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
