INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intrude', '방해하다', '[{"pos": "v.", "ko": "방해하다, 끼어들다"}, {"pos": "v.", "ko": "침입하다, 무단으로 들어가다"}, {"pos": "v.", "ko": "참견하다"}]'::jsonb, 'I didn’t want to intrude on their private conversation, so I waited outside.', '나는 그들의 사적인 대화를 방해하고 싶지 않아서 밖에서 기다렸다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intrusion', '방해', '[{"pos": "n.", "ko": "방해, 참견"}, {"pos": "n.", "ko": "침입, 무단 출입"}, {"pos": "n.", "ko": "간섭"}]'::jsonb, 'Many people feel that constant phone calls are an intrusion into their privacy.', '잦은 전화는 많은 사람들이 사생활을 방해받는다고 느끼게 한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intuition', '직관력', '[{"pos": "n.", "ko": "직관력, 직감"}, {"pos": "n.", "ko": "통찰력"}, {"pos": "n.", "ko": "육감"}]'::jsonb, 'Her intuition told her that something was wrong even before anyone said anything.', '아무도 말하지 않았지만 그녀는 직관적으로 뭔가 잘못됐다는 것을 알았다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('intuitive', '직관적인', '[{"pos": "a.", "ko": "직감에 의한, 직관적인"}, {"pos": "a.", "ko": "이해하기 쉬운"}, {"pos": "a.", "ko": "본능적인"}]'::jsonb, 'The new app has an intuitive design that is easy for everyone to use.', '그 새 앱은 누구나 쉽게 쓸 수 있을 만큼 직관적인 디자인을 가지고 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invade', '침략하다', '[{"pos": "v.", "ko": "침략하다, 침입하다"}, {"pos": "v.", "ko": "(권리·생활 등을) 침해하다"}, {"pos": "v.", "ko": "몰려들다"}]'::jsonb, 'The army planned to invade the neighboring country at dawn.', '군대는 새벽에 이웃 나라를 침략할 계획을 세웠다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invader', '침략자', '[{"pos": "n.", "ko": "침략자, 침입자"}, {"pos": "n.", "ko": "불청객"}]'::jsonb, 'The villagers defended their homes against the foreign invader.', '마을 사람들은 외부 침략자에 맞서 집을 지켰다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invaluable', '매우 귀중한', '[{"pos": "a.", "ko": "매우 귀중한, 값을 매길 수 없는"}, {"pos": "a.", "ko": "대단히 중요한"}]'::jsonb, 'Her advice was invaluable during my difficult times.', '힘든 시기에 그녀의 조언은 매우 귀중했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invariable', '변하지 않는', '[{"pos": "a.", "ko": "변하지 않는, 불변의"}, {"pos": "n.", "ko": "변하지 않는 것"}]'::jsonb, 'The sunrise is an invariable part of each new day.', '해가 뜨는 것은 매일 변하지 않는 일이다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invasion', '침략', '[{"pos": "n.", "ko": "침략, 침입"}, {"pos": "n.", "ko": "침해, 침범"}, {"pos": "n.", "ko": "대량 유입"}]'::jsonb, 'The invasion of the country led to years of conflict and hardship.', '그 나라의 침략은 오랜 갈등과 고난을 불러왔다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invent', '발명하다', '[{"pos": "v.", "ko": "발명하다, 새로 만들다"}, {"pos": "v.", "ko": "(이야기·변명 등을) 지어내다, 꾸며내다"}]'::jsonb, 'He worked hard to invent a machine that could save energy.', '그는 에너지를 절약할 수 있는 기계를 발명하려고 열심히 노력했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invention', '발명품', '[{"pos": "n.", "ko": "발명(품)"}, {"pos": "n.", "ko": "창의력"}, {"pos": "n.", "ko": "지어낸 이야기"}]'::jsonb, 'The invention of the light bulb changed the way people lived.', '전구의 발명은 사람들의 삶을 바꿔 놓았다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inventive', '창의적인', '[{"pos": "a.", "ko": "창의력이 있는, 독창적인"}, {"pos": "a.", "ko": "새로운 것을 잘 만들어내는"}]'::jsonb, 'She is very inventive and always comes up with new ideas.', '그녀는 매우 창의적이라 항상 새로운 아이디어를 낸다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inventor', '발명가', '[{"pos": "n.", "ko": "발명가, 고안자"}]'::jsonb, 'The inventor received an award for his innovative device.', '그 발명가는 혁신적인 기기로 상을 받았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invest', '투자하다', '[{"pos": "v.", "ko": "투자하다"}, {"pos": "v.", "ko": "(시간·노력을) 쏟다"}]'::jsonb, 'Many people decide to invest their money in real estate for the future.', '많은 사람들이 미래를 위해 부동산에 돈을 투자하기로 결정한다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('investigate', '조사하다', '[{"pos": "v.", "ko": "조사하다, 사실을 밝히다"}, {"pos": "v.", "ko": "연구하다, 분석하다"}]'::jsonb, 'The police decided to investigate the cause of the accident thoroughly.', '경찰은 사고 원인을 철저히 조사하기로 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('investigation', '조사', '[{"pos": "n.", "ko": "조사, 사실 확인"}, {"pos": "n.", "ko": "연구, 탐구"}]'::jsonb, 'The investigation into the missing documents took several weeks to complete.', '분실된 문서에 대한 조사는 몇 주가 걸렸다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('investigator', '수사관', '[{"pos": "n.", "ko": "수사관, 조사 담당자"}, {"pos": "n.", "ko": "탐정, 연구자"}]'::jsonb, 'The investigator interviewed several witnesses to gather more information.', '수사관은 더 많은 정보를 얻기 위해 여러 목격자들을 면담했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('investment', '투자', '[{"pos": "n.", "ko": "투자, 자금 투입"}, {"pos": "n.", "ko": "출자금, 투자금"}]'::jsonb, 'Many people consider real estate a safe investment for the future.', '많은 사람들은 부동산을 미래를 위한 안전한 투자라고 생각한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invitation', '초대', '[{"pos": "n.", "ko": "초대, 초청"}, {"pos": "n.", "ko": "초대장, 초청장"}]'::jsonb, 'He received an invitation to attend the school''s graduation ceremony.', '그는 학교 졸업식에 참석하라는 초대를 받았다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('invoke', '적용하다', '[{"pos": "v.", "ko": "(법·규칙 등을) 적용하다, 발동하다"}, {"pos": "v.", "ko": "호소하다, 도움을 청하다"}, {"pos": "v.", "ko": "(근거로) 언급하다, 인용하다"}]'::jsonb, 'The government decided to invoke emergency powers during the crisis.', '정부는 위기 상황에서 비상 권한을 적용하기로 결정했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('involuntary', '무의식적인', '[{"pos": "a.", "ko": "무의식적인, 저절로 일어나는"}, {"pos": "a.", "ko": "원치 않는, 강제적인"}]'::jsonb, 'Sneezing is often an involuntary reaction to dust or pollen.', '재채기는 종종 먼지나 꽃가루에 대한 무의식적인 반응이다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('involve', '포함하다', '[{"pos": "v.", "ko": "포함하다, 수반하다"}, {"pos": "v.", "ko": "관계시키다, 연루시키다"}, {"pos": "v.", "ko": "참여시키다"}]'::jsonb, 'The new project will involve students from different grade levels.', '새로운 프로젝트는 여러 학년의 학생들을 포함할 것이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('involvement', '참여', '[{"pos": "n.", "ko": "참여, 관여"}, {"pos": "n.", "ko": "관련, 연루"}]'::jsonb, 'Her involvement in volunteer work inspired many of her classmates.', '그녀의 봉사활동 참여는 많은 반 친구들에게 영감을 주었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('irrational', '비이성적인', '[{"pos": "a.", "ko": "비이성적인, 논리적이지 않은"}, {"pos": "a.", "ko": "이성을 잃은, 터무니없는"}]'::jsonb, 'His fear of harmless insects is completely irrational.', '그의 해롭지 않은 곤충에 대한 두려움은 완전히 비이성적이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('irrelevant', '관련 없는', '[{"pos": "a.", "ko": "관련 없는, 무관한"}, {"pos": "a.", "ko": "중요하지 않은"}]'::jsonb, 'Your personal opinion is irrelevant to the main topic of discussion.', '네 개인적인 의견은 논의의 주요 주제와 관련이 없다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('irresistible', '저항할 수 없는', '[{"pos": "a.", "ko": "저항할 수 없는, 억누를 수 없는"}, {"pos": "a.", "ko": "매력적인, 거부할 수 없는"}]'::jsonb, 'The smell of freshly baked bread was simply irresistible.', '갓 구운 빵 냄새는 정말로 저항할 수 없었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('irritate', '짜증나게 하다', '[{"pos": "v.", "ko": "짜증나게 하다, 화나게 하다"}, {"pos": "v.", "ko": "자극하다, (피부를) 거슬리게 하다"}]'::jsonb, 'Loud noises can easily irritate people who are trying to concentrate.', '시끄러운 소음은 집중하려는 사람들을 쉽게 짜증나게 할 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('irritation', '짜증', '[{"pos": "n.", "ko": "짜증, 불쾌감"}, {"pos": "n.", "ko": "자극, 염증"}]'::jsonb, 'His constant interruptions were a source of irritation for everyone in the room.', '그의 끊임없는 방해는 방 안 모든 사람의 짜증을 유발했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('issue', '문제', '[{"pos": "n.", "ko": "문제, 논쟁점"}, {"pos": "n.", "ko": "발행물, 출판물"}, {"pos": "v.", "ko": "발표하다, 공표하다"}, {"pos": "v.", "ko": "발행하다, 내주다"}]'::jsonb, 'Environmental pollution has become a serious issue in many cities.', '환경 오염은 많은 도시에서 심각한 문제가 되었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('jealous', '질투하는', '[{"pos": "a.", "ko": "질투하는, 시기하는"}, {"pos": "a.", "ko": "질투심이 강한"}]'::jsonb, 'She felt jealous when her friend received more attention than she did.', '그녀는 친구가 자신보다 더 많은 관심을 받을 때 질투를 느꼈다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('journalism', '언론 활동', '[{"pos": "n.", "ko": "언론 활동, 기사 작성"}, {"pos": "n.", "ko": "언론계, 보도 분야"}]'::jsonb, 'He studied journalism because he wanted to become a reporter.', '그는 기자가 되고 싶어서 언론학을 공부했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('journalist', '기자', '[{"pos": "n.", "ko": "기자, 언론인"}, {"pos": "n.", "ko": "보도 담당자"}]'::jsonb, 'The journalist interviewed several witnesses at the scene of the accident.', '기자는 사고 현장에서 여러 목격자들을 인터뷰했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('judge', '재판관', '[{"pos": "n.", "ko": "재판관, 판사"}, {"pos": "n.", "ko": "심사위원, 심판"}, {"pos": "v.", "ko": "판단하다, 평가하다"}, {"pos": "v.", "ko": "재판하다, 판결하다"}]'::jsonb, 'The judge listened carefully to both sides before making a decision.', '재판관은 결정을 내리기 전에 양측의 말을 주의 깊게 들었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('judgment', '판단', '[{"pos": "n.", "ko": "판단, 판단력"}, {"pos": "n.", "ko": "판정, 결정"}, {"pos": "n.", "ko": "판결, 재판 결과"}]'::jsonb, 'Good judgment is important when making difficult choices in life.', '인생에서 어려운 선택을 할 때는 올바른 판단이 중요하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('just', '공정한', '[{"pos": "a.", "ko": "공정한, 올바른"}, {"pos": "ad.", "ko": "막, 방금"}, {"pos": "ad.", "ko": "단지, 그저"}]'::jsonb, 'A just leader always treats everyone with fairness and respect.', '공정한 지도자는 항상 모두를 공평하게 대한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('justice', '정의', '[{"pos": "n.", "ko": "정의, 공정"}, {"pos": "n.", "ko": "사법, 재판"}]'::jsonb, 'Many people fight for justice when they see unfair treatment.', '많은 사람들이 부당한 대우를 보면 정의를 위해 싸운다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('justification', '정당화', '[{"pos": "n.", "ko": "정당화, 변명"}, {"pos": "n.", "ko": "정당한 이유"}]'::jsonb, 'There was no justification for his rude behavior during the meeting.', '회의 중 그의 무례한 행동에는 어떤 정당화도 없었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('justified', '정당한', '[{"pos": "a.", "ko": "정당한, 타당한"}, {"pos": "a.", "ko": "당연한"}]'::jsonb, 'Her anger was justified because she had been treated unfairly.', '그녀의 분노는 부당한 대우를 받았으니 정당했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
