INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('modernize', '현대화하다', '[{"pos": "v.", "ko": "현대화하다, 현대식으로 만들다"}]'::jsonb, 'The company plans to modernize its old factories next year.', '그 회사는 내년에 낡은 공장들을 현대화할 계획이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
