INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('modification', '변경', '[{"pos": "n.", "ko": "변경, 수정"}]'::jsonb, 'The teacher suggested a modification to improve my essay.', '선생님이 내 에세이를 더 좋게 하려고 수정을 제안하셨다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
