INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('notification', '알림', '[{"pos": "n.", "ko": "알림, 통지"}]'::jsonb, 'You will receive a notification when your package has shipped.', '택배가 발송되면 알림을 받게 됩니다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('notify', '알리다', '[{"pos": "v.", "ko": "알리다, 통보하다"}]'::jsonb, 'Please notify me if there are any changes to the schedule.', '일정에 변경이 있으면 저에게 알려주세요.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('notion', '생각', '[{"pos": "n.", "ko": "생각, 관념"}, {"pos": "n.", "ko": "개념"}]'::jsonb, 'She had a clear notion of what she wanted to achieve.', '그녀는 자신이 이루고 싶은 것에 대한 분명한 생각이 있었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nourish', '영양을 주다', '[{"pos": "v.", "ko": "영양분을 공급하다"}, {"pos": "v.", "ko": "(감정·생각 등을) 키우다, 기르다"}]'::jsonb, 'Parents should nourish their children with healthy food and love.', '부모는 자녀에게 건강한 음식과 사랑으로 영양을 줘야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nourishment', '영양', '[{"pos": "n.", "ko": "영양, 음식"}, {"pos": "n.", "ko": "육성, 양육"}]'::jsonb, 'Proper nourishment is essential for a child''s growth and development.', '적절한 영양은 아이의 성장과 발달에 꼭 필요하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('novel', '소설', '[{"pos": "n.", "ko": "(장편) 소설"}, {"pos": "a.", "ko": "새로운, 신기한"}]'::jsonb, 'She spent the weekend reading a novel by her favorite author.', '그녀는 주말 내내 좋아하는 작가의 소설을 읽었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('novelist', '소설가', '[{"pos": "n.", "ko": "소설가"}]'::jsonb, 'The novelist is working on a new book set in the future.', '그 소설가는 미래를 배경으로 한 새 책을 집필 중이다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('novelty', '새로움', '[{"pos": "n.", "ko": "새로움, 참신함"}, {"pos": "n.", "ko": "새로운 것, 신기한 물건"}]'::jsonb, 'The novelty of the new technology quickly attracted many users.', '새로운 기술의 새로움이 많은 이용자를 빠르게 끌어들였다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('numeral', '숫자', '[{"pos": "n.", "ko": "숫자, 수자"}, {"pos": "a.", "ko": "숫자를 나타내는"}]'::jsonb, 'The teacher wrote each numeral on the board for the students to read.', '선생님이 칠판에 각 숫자를 써서 학생들이 읽게 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('numerical', '수와 관련된', '[{"pos": "a.", "ko": "수와 관련된"}, {"pos": "a.", "ko": "숫자로 나타낸"}]'::jsonb, 'The report included a numerical analysis of the survey results.', '그 보고서에는 설문 결과에 대한 수치 분석이 포함되어 있었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('numerous', '많은', '[{"pos": "a.", "ko": "많은, 수많은"}, {"pos": "a.", "ko": "다수의"}]'::jsonb, 'There are numerous reasons why people choose to study abroad.', '사람들이 유학을 선택하는 이유는 매우 많다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('numerously', '수없이', '[{"pos": "ad.", "ko": "수없이, 많이"}]'::jsonb, 'Wildflowers grew numerously along the side of the mountain trail.', '야생화가 산길 옆에 수없이 피어 있었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nurse', '간호사', '[{"pos": "n.", "ko": "간호사"}, {"pos": "v.", "ko": "간호하다, 돌보다"}, {"pos": "n.", "ko": "유모"}]'::jsonb, 'The nurse checked the patient''s temperature every hour.', '간호사는 환자의 체온을 매시간 확인했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nursery', '유치원', '[{"pos": "n.", "ko": "유치원, 탁아소"}, {"pos": "n.", "ko": "아이 방"}, {"pos": "a.", "ko": "유치원의"}]'::jsonb, 'Parents dropped their children off at the nursery before going to work.', '부모들은 출근 전에 아이를 유치원에 데려다주었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nurture', '양육하다', '[{"pos": "v.", "ko": "양육하다, 키우다"}, {"pos": "n.", "ko": "양육, 육성"}, {"pos": "v.", "ko": "(계획·생각 등을) 키우다"}]'::jsonb, 'It is important to nurture children''s creativity from an early age.', '어릴 때부터 아이들의 창의성을 키우는 것이 중요하다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nutrient', '영양소', '[{"pos": "n.", "ko": "영양소, 영양분"}]'::jsonb, 'Vitamins and minerals are essential nutrients for our health.', '비타민과 미네랄은 건강에 꼭 필요한 영양소다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nutrition', '영양', '[{"pos": "n.", "ko": "영양, 영양 섭취"}]'::jsonb, 'Good nutrition is necessary for proper growth and development.', '올바른 성장을 위해서는 좋은 영양이 필요하다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nutritional', '영양상의', '[{"pos": "a.", "ko": "영양상의, 영양과 관련된"}]'::jsonb, 'The nutritional value of fruits makes them a healthy snack.', '과일은 영양가가 높아 건강한 간식이 된다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nutritious', '영양가 있는', '[{"pos": "a.", "ko": "영양가 있는, 영양분이 많은"}]'::jsonb, 'A nutritious breakfast helps you concentrate better in class.', '영양가 있는 아침 식사는 수업에 더 잘 집중하게 해준다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('obedience', '복종', '[{"pos": "n.", "ko": "복종, 순종"}, {"pos": "n.", "ko": "준수"}]'::jsonb, 'Obedience to rules is important for a safe school environment.', '안전한 학교 환경을 위해 규칙에 복종하는 것이 중요하다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('obedient', '복종하는', '[{"pos": "a.", "ko": "복종하는, 순종하는"}]'::jsonb, 'The obedient dog followed every command given by its owner.', '그 개는 주인의 모든 명령에 복종했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
