INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('passive', '수동적인', '[{"pos": "a.", "ko": "수동적인"}, {"pos": "a.", "ko": "소극적인"}]'::jsonb, 'A passive attitude can make it hard to achieve your goals.', '수동적인 태도는 목표를 이루기 어렵게 만들 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
