INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('punctual', '시간 엄수하는', '[{"pos": "a.", "ko": "시간을 잘 지키는, 시간을 엄수하는"}]'::jsonb, 'He is always punctual and never late for meetings.', '그는 항상 시간을 잘 지켜 회의에 늦지 않는다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
