INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relevance', '관련성', '[{"pos": "n.", "ko": "관련성, 적합성"}, {"pos": "n.", "ko": "타당성"}]'::jsonb, 'The teacher questioned the relevance of his answer to the topic.', '선생님은 그의 대답이 주제와 관련이 있는지 의문을 가졌다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relevant', '관련된', '[{"pos": "a.", "ko": "관련된, 관계가 있는"}]'::jsonb, 'Only relevant information should be included in your report.', '보고서에는 관련된 정보만 포함해야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reliability', '신뢰도', '[{"pos": "n.", "ko": "신뢰도, 믿을 수 있음"}]'::jsonb, 'The reliability of the data was confirmed by several experiments.', '그 데이터의 신뢰도는 여러 실험을 통해 확인되었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reliable', '믿을 만한', '[{"pos": "a.", "ko": "믿을 만한, 신뢰할 수 있는"}]'::jsonb, 'He is a reliable friend who always keeps his promises.', '그는 항상 약속을 지키는 믿을 만한 친구다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reliance', '의존', '[{"pos": "n.", "ko": "의존, 의지"}, {"pos": "n.", "ko": "신뢰"}]'::jsonb, 'Excessive reliance on technology can cause various problems.', '기술에 대한 지나친 의존은 여러 문제를 일으킬 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reliant', '의존하는', '[{"pos": "a.", "ko": "의존하는, 의지하는"}, {"pos": "a.", "ko": "신뢰하는"}]'::jsonb, 'Some animals are highly reliant on their parents for survival.', '일부 동물은 살아남기 위해 부모에게 크게 의존한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relief', '안도', '[{"pos": "n.", "ko": "안도, 안심"}, {"pos": "n.", "ko": "(고통, 근심 등의) 경감, 완화"}, {"pos": "n.", "ko": "구호, 원조 물자"}]'::jsonb, 'She felt great relief after hearing the good news.', '그녀는 좋은 소식을 듣고 큰 안도를 느꼈다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relieve', '경감하다', '[{"pos": "v.", "ko": "(고통, 고민 등을) 경감하다, 완화하다"}]'::jsonb, 'Taking a short walk can relieve stress and clear your mind.', '잠깐 산책을 하면 스트레스를 경감하고 머리를 맑게 할 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relieved', '안도하는', '[{"pos": "a.", "ko": "안도하는, 다행으로 여기는"}]'::jsonb, 'I was relieved to find my lost wallet at the office.', '나는 잃어버린 지갑을 사무실에서 찾아서 안도했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('religion', '종교', '[{"pos": "n.", "ko": "종교"}, {"pos": "n.", "ko": "신조, 신앙"}]'::jsonb, 'People around the world practice many different religions.', '전 세계 사람들은 다양한 종교를 믿고 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
