INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('selfish', '이기적인', '[{"pos": "a.", "ko": "자기만 생각하는, 이기적인"}, {"pos": "a.", "ko": "남을 배려하지 않는"}]'::jsonb, 'It is selfish to ignore your friends when they need your help.', '친구가 도움이 필요할 때 무시하는 것은 이기적인 행동이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
