INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('significance', '중요성', '[{"pos": "n.", "ko": "중요성, 의미"}, {"pos": "n.", "ko": "(말·행동의) 의의"}]'::jsonb, 'The significance of this discovery cannot be underestimated.', '이 발견의 중요성은 아무리 강조해도 지나치지 않다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
