INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('similar', '비슷한', '[{"pos": "a.", "ko": "비슷한, 유사한"}]'::jsonb, 'The two paintings look similar but were created by different artists.', '두 그림은 비슷해 보이지만 서로 다른 화가가 그렸다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
