INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stimulate', '자극하다', '[{"pos": "v.", "ko": "자극하다, 촉진하다"}, {"pos": "v.", "ko": "격려하다, 고무하다"}]'::jsonb, 'Bright colors can stimulate a child''s interest in learning.', '밝은 색깔은 아이의 학습 흥미를 자극할 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stimulation', '자극', '[{"pos": "n.", "ko": "자극, 흥분"}, {"pos": "n.", "ko": "격려, 고무"}]'::jsonb, 'The stimulation from new experiences helps the brain grow.', '새로운 경험에서 오는 자극이 두뇌 발달에 도움이 된다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stimulus', '자극제', '[{"pos": "n.", "ko": "자극제, 자극이 되는 것"}, {"pos": "n.", "ko": "고무, 격려"}]'::jsonb, 'A reward can be a strong stimulus for students to study harder.', '보상은 학생들이 더 열심히 공부하도록 하는 강한 자극제가 될 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strain', '긴장', '[{"pos": "n.", "ko": "긴장, 피로"}, {"pos": "n.", "ko": "부담, 중압"}, {"pos": "v.", "ko": "애쓰다, 노력하다"}, {"pos": "v.", "ko": "(근육 등을) 혹사시키다"}]'::jsonb, 'Preparing for the exam put a lot of strain on the students.', '시험 준비로 학생들은 큰 긴장을 겪었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strait', '해협', '[{"pos": "n.", "ko": "좁은 바닷길, 해협"}, {"pos": "n.", "ko": "곤란한 상황, 곤경"}]'::jsonb, 'The ship sailed carefully through the narrow strait between the two islands.', '배는 두 섬 사이의 좁은 해협을 조심스럽게 통과했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strengthen', '강화하다', '[{"pos": "v.", "ko": "강화하다, 더 튼튼하게 하다"}, {"pos": "v.", "ko": "강해지다, 힘을 얻다"}]'::jsonb, 'Regular exercise can strengthen your muscles and improve your health.', '규칙적인 운동은 근육을 강화하고 건강을 증진시킨다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stress', '스트레스', '[{"pos": "n.", "ko": "긴장, 스트레스"}, {"pos": "n.", "ko": "압박, 중점"}, {"pos": "v.", "ko": "강조하다, 중점을 두다"}]'::jsonb, 'Too much stress can affect your ability to concentrate in class.', '지나친 스트레스는 수업에서 집중력을 떨어뜨릴 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strict', '엄격한', '[{"pos": "a.", "ko": "엄격한, 엄한"}, {"pos": "a.", "ko": "정확한, 엄밀한"}]'::jsonb, 'Our teacher is very strict about homework deadlines.', '우리 선생님은 숙제 제출 기한에 매우 엄격하다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strictly', '엄격히', '[{"pos": "ad.", "ko": "엄격히, 엄하게"}, {"pos": "ad.", "ko": "정확히, 엄밀히"}]'::jsonb, 'Students are strictly forbidden to use cell phones during exams.', '학생들은 시험 중에 휴대폰 사용이 엄격히 금지된다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('structural', '구조상의', '[{"pos": "a.", "ko": "구조상의, 조직상의"}]'::jsonb, 'Engineers checked for any structural damage after the earthquake.', '엔지니어들이 지진 후 구조상의 손상이 있는지 점검했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('structure', '구조', '[{"pos": "n.", "ko": "구조, 체계"}, {"pos": "n.", "ko": "건축물, 구조물"}, {"pos": "v.", "ko": "구성하다, 조직하다"}]'::jsonb, 'The structure of the essay should include an introduction, body, and conclusion.', '에세이의 구조는 서론, 본론, 결론을 포함해야 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('struggle', '고군분투하다', '[{"pos": "v.", "ko": "고군분투하다, 힘겹게 싸우다"}, {"pos": "n.", "ko": "분투, 노력"}]'::jsonb, 'She had to struggle to balance her studies and part-time job.', '그녀는 학업과 아르바이트를 병행하려고 고군분투했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subconscious', '잠재의식의', '[{"pos": "a.", "ko": "잠재의식의"}, {"pos": "n.", "ko": "잠재의식"}]'::jsonb, 'Some fears are rooted deep in our subconscious mind without us realizing it.', '어떤 두려움은 우리가 인식하지 못하는 잠재의식 깊은 곳에 뿌리를 두고 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subconsciously', '잠재의식 속에서', '[{"pos": "ad.", "ko": "잠재의식 속에서, 무의식적으로"}]'::jsonb, 'He subconsciously tapped his foot whenever he felt nervous during the test.', '그는 시험 중에 긴장할 때마다 잠재의식적으로 발을 두드렸다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subject', '주제', '[{"pos": "n.", "ko": "주제, 화제"}, {"pos": "n.", "ko": "과목, 학과"}, {"pos": "n.", "ko": "피실험자, 대상"}, {"pos": "a.", "ko": "영향받기 쉬운, 지배를 받는"}, {"pos": "v.", "ko": "지배하다, 복종시키다"}]'::jsonb, 'The main subject of the discussion was how to improve student safety.', '토론의 주요 주제는 학생 안전을 어떻게 높일지였다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
