INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subscription', '구독', '[{"pos": "n.", "ko": "구독, 구독료"}, {"pos": "n.", "ko": "가입, 신청"}, {"pos": "n.", "ko": "기부"}]'::jsonb, 'I renewed my subscription to the science magazine for another year.', '나는 과학 잡지 구독을 1년 더 연장했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
