INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suburb', '교외', '[{"pos": "n.", "ko": "교외, 도시 주변 주택지"}]'::jsonb, 'Many families prefer to live in the suburb for a quieter environment.', '많은 가족들이 더 조용한 환경을 위해 교외에서 살기를 선호한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suburban', '교외의', '[{"pos": "a.", "ko": "교외의, 교외에 사는"}]'::jsonb, 'Suburban areas often have more parks than city centers.', '교외 지역에는 도심보다 공원이 더 많은 경우가 많다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('succeed', '성공하다', '[{"pos": "v.", "ko": "성공하다, 성과를 거두다"}, {"pos": "v.", "ko": "뒤를 잇다, 계승하다"}]'::jsonb, 'If you work hard and stay focused, you will succeed in your goals.', '열심히 노력하고 집중하면 목표를 이룰 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('success', '성공', '[{"pos": "n.", "ko": "성공, 성취"}, {"pos": "n.", "ko": "출세"}]'::jsonb, 'Her success as a writer inspired many young people to follow their dreams.', '그녀의 작가로서의 성공은 많은 젊은이들에게 꿈을 따르도록 영감을 주었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
