INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('successfully', '성공적으로', '[{"pos": "ad.", "ko": "성공적으로, 잘"}]'::jsonb, 'She successfully completed the marathon despite the difficult weather conditions.', '그녀는 힘든 날씨에도 마라톤을 성공적으로 완주했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
