INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('successive', '연속적인', '[{"pos": "a.", "ko": "연속적인, 계속되는"}]'::jsonb, 'He won three successive championships in his sporting career.', '그는 운동 선수 생활 동안 세 번 연속으로 우승했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
