INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('technological', '과학 기술의', '[{"pos": "a.", "ko": "과학 기술의, 기술적인"}, {"pos": "a.", "ko": "첨단 기술의"}]'::jsonb, 'Technological advances have changed the way we communicate.', '과학 기술의 발전이 우리의 소통 방식을 바꿔 놓았다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('technologist', '과학 기술자', '[{"pos": "n.", "ko": "과학 기술자, 기술 전문가"}]'::jsonb, 'A technologist developed a new device for faster data transfer.', '한 과학 기술자가 더 빠른 데이터 전송을 위한 새 기기를 개발했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('technology', '과학 기술', '[{"pos": "n.", "ko": "과학 기술, 기술"}, {"pos": "n.", "ko": "공학, 기술 체계"}]'::jsonb, 'Modern technology has made our daily lives much more convenient.', '현대 과학 기술은 우리의 일상을 훨씬 더 편리하게 만들었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('telecommute', '재택근무하다', '[{"pos": "v.", "ko": "재택근무하다, 원격 근무하다"}]'::jsonb, 'Many employees now telecommute instead of going to the office every day.', '많은 직원들이 이제 매일 출근하는 대신 재택근무를 한다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('telegraph', '전신', '[{"pos": "n.", "ko": "전신, 전보"}, {"pos": "v.", "ko": "전보를 보내다, 알리다"}, {"pos": "v.", "ko": "(몸짓 등으로) 넌지시 알리다"}]'::jsonb, 'Before telephones, people sent messages using the telegraph.', '전화가 나오기 전에는 사람들은 전신을 이용해 메시지를 보냈다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('telescope', '망원경', '[{"pos": "n.", "ko": "망원경"}]'::jsonb, 'He used a telescope to observe the stars at night.', '그는 밤에 별을 관찰하기 위해 망원경을 사용했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temper', '성미', '[{"pos": "n.", "ko": "성미, 기질"}, {"pos": "n.", "ko": "화, 분노"}, {"pos": "n.", "ko": "기분, 심리 상태"}]'::jsonb, 'She has a gentle temper and rarely gets angry.', '그녀는 성미가 온화해서 좀처럼 화를 내지 않는다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temperament', '기질', '[{"pos": "n.", "ko": "기질, 성격"}, {"pos": "n.", "ko": "성향, 성질"}]'::jsonb, 'His artistic temperament makes him sensitive to beauty.', '그의 예술가적 기질은 아름다움에 민감하게 만든다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temperance', '절제', '[{"pos": "n.", "ko": "절제, 자제"}, {"pos": "n.", "ko": "금주, 술을 삼감"}]'::jsonb, 'Practicing temperance helps people make wiser decisions in difficult situations.', '절제를 실천하면 어려운 상황에서 더 현명한 결정을 내릴 수 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temperate', '온화한', '[{"pos": "a.", "ko": "온화한, 따뜻한"}, {"pos": "a.", "ko": "절제하는, 지나치지 않는"}, {"pos": "a.", "ko": "온건한, 극단적이지 않은"}]'::jsonb, 'The temperate climate of the region makes it ideal for growing grapes.', '그 지역의 온화한 기후는 포도를 재배하기에 이상적이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temperature', '온도', '[{"pos": "n.", "ko": "온도, 기온"}, {"pos": "n.", "ko": "체온"}]'::jsonb, 'The temperature dropped quickly after the sun set behind the mountains.', '해가 산 뒤로 지자 온도가 급격히 떨어졌다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temporarily', '일시적으로', '[{"pos": "ad.", "ko": "일시적으로, 잠깐"}, {"pos": "ad.", "ko": "임시로"}]'::jsonb, 'The museum is temporarily closed for renovations until next month.', '박물관은 다음 달까지 보수 공사로 일시적으로 문을 닫는다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temporary', '일시적인', '[{"pos": "a.", "ko": "일시적인, 잠정적인"}, {"pos": "a.", "ko": "임시의, 한시적인"}]'::jsonb, 'He found a temporary job during his summer vacation to earn some money.', '그는 여름방학 동안 돈을 벌기 위해 일시적인 일을 구했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tempt', '유혹하다', '[{"pos": "v.", "ko": "유혹하다, 끌어들이다"}, {"pos": "v.", "ko": "~할 마음이 들게 하다"}]'::jsonb, 'The smell of freshly baked bread tempted her to enter the bakery.', '갓 구운 빵 냄새가 그녀를 빵집으로 유혹했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temptation', '유혹', '[{"pos": "n.", "ko": "유혹"}, {"pos": "n.", "ko": "마음이 끌리는 것"}]'::jsonb, 'He resisted the temptation to check his phone during class.', '그는 수업 중에 휴대폰을 확인하고 싶은 유혹을 참았다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tend', '경향이 있다', '[{"pos": "v.", "ko": "~하는 경향이 있다"}, {"pos": "v.", "ko": "돌보다, 보살피다"}]'::jsonb, 'Teenagers tend to stay up late on weekends and sleep in the next morning.', '십대들은 주말에 늦게까지 깨어 있고 다음 날 늦잠을 자는 경향이 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tendency', '경향', '[{"pos": "n.", "ko": "경향, 성향"}, {"pos": "n.", "ko": "추세"}]'::jsonb, 'There is a growing tendency among people to shop online rather than in stores.', '사람들 사이에서 매장에서보다 온라인으로 쇼핑하는 경향이 커지고 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tender', '부드러운', '[{"pos": "a.", "ko": "부드러운, 연한"}, {"pos": "a.", "ko": "다정한, 상냥한"}, {"pos": "v.", "ko": "제출하다, 제공하다 (격식체)"}]'::jsonb, 'The meat became very tender after being cooked slowly for several hours.', '고기는 몇 시간 동안 천천히 익혀서 매우 부드러워졌다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tenderness', '상냥함', '[{"pos": "n.", "ko": "상냥함, 다정함"}, {"pos": "n.", "ko": "부드러움, 연함"}, {"pos": "n.", "ko": "민감함, 아픔"}]'::jsonb, 'She showed great tenderness when comforting her younger brother.', '그녀는 남동생을 위로할 때 큰 상냥함을 보였다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tense', '긴장한', '[{"pos": "a.", "ko": "긴장한, 불안한"}, {"pos": "a.", "ko": "팽팽한, 당겨진"}, {"pos": "n.", "ko": "시제"}]'::jsonb, 'Everyone in the room looked tense before the important announcement was made.', '중요한 발표가 있기 전 방 안의 모두가 긴장한 표정이었다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tension', '긴장', '[{"pos": "n.", "ko": "긴장 (상태)"}, {"pos": "n.", "ko": "팽팽함"}]'::jsonb, 'There was a lot of tension between the two teams during the final match.', '결승전에서 두 팀 사이에는 긴장이 감돌았다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('term', '용어', '[{"pos": "n.", "ko": "용어, 단어"}, {"pos": "n.", "ko": "기간, 학기"}, {"pos": "n.", "ko": "조건, 조항"}, {"pos": "v.", "ko": "이름 짓다, 부르다"}]'::jsonb, 'The term ''ecosystem'' is often used in biology classes at school.', '''생태계''라는 용어는 학교 생물 수업에서 자주 사용된다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terminal', '맨 끝의', '[{"pos": "a.", "ko": "맨 끝의, 말단의"}, {"pos": "a.", "ko": "말기의, 마지막의"}, {"pos": "n.", "ko": "종점, 터미널"}]'::jsonb, 'The train stopped at the terminal station, where all passengers had to get off.', '기차는 맨 끝 역에 멈춰서 모든 승객이 내려야 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terminate', '종결하다', '[{"pos": "v.", "ko": "종결하다, 끝내다"}, {"pos": "v.", "ko": "종결되다, 끝나다"}]'::jsonb, 'The company decided to terminate the contract due to repeated delays.', '회사는 반복된 지연 때문에 계약을 종결하기로 결정했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('termination', '종결', '[{"pos": "n.", "ko": "종결, 종료"}, {"pos": "n.", "ko": "해고, 중단"}]'::jsonb, 'The termination of the agreement was announced at the meeting.', '회의에서 계약의 종결이 발표되었다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terrestrial', '지구의', '[{"pos": "a.", "ko": "지구의, 지상의"}, {"pos": "a.", "ko": "육지의, 육상에 사는"}]'::jsonb, 'Scientists study terrestrial plants to understand how life adapts on land.', '과학자들은 지구의 식물을 연구하여 생명이 육지에 어떻게 적응하는지 알아본다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terrible', '끔찍한', '[{"pos": "a.", "ko": "끔찍한, 무서운"}, {"pos": "a.", "ko": "심각한, 매우 나쁜"}, {"pos": "a.", "ko": "엄청난, 대단한"}]'::jsonb, 'The earthquake caused terrible damage to the small village.', '지진으로 작은 마을에 끔찍한 피해가 발생했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terribly', '몹시', '[{"pos": "ad.", "ko": "몹시, 매우"}, {"pos": "ad.", "ko": "끔찍하게, 심하게"}]'::jsonb, 'She was terribly worried about the results of her exam.', '그녀는 시험 결과가 몹시 걱정됐다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terrify', '겁에 질리게 하다', '[{"pos": "v.", "ko": "겁에 질리게 하다"}, {"pos": "v.", "ko": "무섭게 하다"}]'::jsonb, 'The loud thunder terrified the children during the storm.', '폭풍우 속의 천둥 소리가 아이들을 겁에 질리게 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terrifying', '아주 무서운', '[{"pos": "a.", "ko": "아주 무서운, 공포를 주는"}, {"pos": "a.", "ko": "겁나게 하는"}]'::jsonb, 'The movie was so terrifying that some people left the theater early.', '그 영화가 너무 무서워서 몇몇 사람들은 일찍 극장을 나갔다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('territorial', '영토의', '[{"pos": "a.", "ko": "영토의, 땅과 관련된"}, {"pos": "a.", "ko": "영역을 지키는"}]'::jsonb, 'There are often territorial disputes between neighboring countries.', '이웃 나라들 사이에는 종종 영토 분쟁이 있다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('territory', '영토', '[{"pos": "n.", "ko": "영토, 국토"}, {"pos": "n.", "ko": "지역, 구역"}, {"pos": "n.", "ko": "분야, 영역"}]'::jsonb, 'The country expanded its territory after the war.', '그 나라는 전쟁 후에 영토를 확장했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terror', '공포', '[{"pos": "n.", "ko": "공포, 극심한 두려움"}, {"pos": "n.", "ko": "테러 행위"}]'::jsonb, 'The sudden explosion filled the crowd with terror.', '갑작스러운 폭발로 군중은 공포에 휩싸였다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
