INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('vary', '다르다', '[{"pos": "v.", "ko": "다르다, 서로 다르게 하다"}, {"pos": "v.", "ko": "달라지다, 변화하다"}, {"pos": "v.", "ko": "변화를 주다, 다양하게 하다"}]'::jsonb, 'The results may vary depending on how the experiment is conducted.', '실험을 어떻게 하느냐에 따라 결과가 다를 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
