INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('verbally', '말로', '[{"pos": "ad.", "ko": "말로, 구두로"}]'::jsonb, 'She apologized verbally instead of writing a letter.', '그녀는 편지를 쓰는 대신 말로 사과했다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
