INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('voluntarily', '자발적으로', '[{"pos": "ad.", "ko": "자발적으로, 스스로"}, {"pos": "ad.", "ko": "자원해서"}]'::jsonb, 'She voluntarily helped clean the park every weekend.', '그녀는 매주 주말마다 자발적으로 공원 청소를 도왔다.', ARRAY['derived']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('voluntary', '자발적인', '[{"pos": "a.", "ko": "자발적인, 자진해서 하는"}, {"pos": "a.", "ko": "자원봉사의, 무보수의"}]'::jsonb, 'Participation in the program is completely voluntary.', '이 프로그램 참여는 전적으로 자발적이다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
