INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('vote', '투표하다', '[{"pos": "v.", "ko": "투표하다"}, {"pos": "n.", "ko": "투표"}, {"pos": "n.", "ko": "표"}]'::jsonb, 'Citizens over eighteen can vote in the national elections.', '18세 이상 시민은 전국 선거에서 투표할 수 있다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
