INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('withdraw', '인출하다', '[{"pos": "v.", "ko": "(예금 등을) 인출하다"}, {"pos": "v.", "ko": "철수하다, 물러나다"}, {"pos": "v.", "ko": "(약속·지원 등을) 철회하다"}, {"pos": "v.", "ko": "(조직·학교 등을) 그만두다"}]'::jsonb, 'She had to withdraw some money from her bank account to pay the bills.', '그녀는 청구서를 내기 위해 은행 계좌에서 돈을 인출해야 했다.', ARRAY['headword']) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
